use std::{fs,path::Path};use serde_json::{Value,json};use sha2::{Digest,Sha256};fn main(){let r=Path::new("/home/ubuntu/src/zopro-perf-work/fq6-toom175");fs::rename(r.join("native"),r.join("second-native")).unwrap();for f in["build-plan.json","build-pins.json","kernel.rs"]{fs::copy(r.join(f),r.join(format!("{f}.before-test-import"))).unwrap();}for f in["kernel.rs","source/crates/zopro-bn254/src/fq6/toom.rs"]{let p=r.join(f);let s=fs::read_to_string(&p).unwrap();assert_eq!(s.matches("use ark_ff::{BigInt, Field, UniformRand};").count(),1);fs::write(p,s.replace("use ark_ff::{BigInt, Field, UniformRand};","use ark_ff::{BigInt, Field, UniformRand, AdditiveGroup};")).unwrap();}let p=r.join("build-plan.json");let mut plan:Value=serde_json::from_slice(&fs::read(&p).unwrap()).unwrap();plan["steps"]=json!(plan["steps"].as_array().unwrap().iter().filter(|s|s["name"]!="link-off").cloned().collect::<Vec<_>>());fs::write(p,serde_json::to_vec_pretty(&plan).unwrap()).unwrap();let p=r.join("build-pins.json");let mut pins:Value=serde_json::from_slice(&fs::read(&p).unwrap()).unwrap();for f in["kernel.rs","source/crates/zopro-bn254/src/fq6/toom.rs","repair-tests.rs"]{let p=r.join(f);pins[p.display().to_string()]=json!(format!("{:x}",Sha256::digest(fs::read(&p).unwrap())));}fs::write(p,serde_json::to_vec_pretty(&pins).unwrap()).unwrap();}
